package com.yeyamo_mobile.api.culture_service.application;
import com.yeyamo_mobile.api.culture_service.domain.*;import jakarta.validation.constraints.*;import java.time.Instant;import java.util.*;
public final class ChallengeDtos{private ChallengeDtos(){}public record ChallengeResponse(UUID id,String title,String description,CultureChallenge.Type type,String countryCode,String languageCode,Instant startsAt,Instant endsAt,CultureChallenge.Status status,UUID rewardDefinitionId,boolean moderationRequired,List<String>prompts){public static ChallengeResponse from(CultureChallenge c,List<CultureChallengePrompt>p){return new ChallengeResponse(c.getId(),c.getTitle(),c.getDescription(),c.getType(),c.getCountryCode(),c.getLanguageCode(),c.getStartsAt(),c.getEndsAt(),c.getStatus(),c.getRewardDefinitionId(),c.isModerationRequired(),p.stream().map(CultureChallengePrompt::getPrompt).toList());}}public record SubmissionRequest(UUID postId,UUID cultureContributionId,List<UUID>mediaIds,String languageCode,String translation,boolean recordsAnotherPerson,boolean consentConfirmed,boolean anonymized,String sourcePersonName,boolean involvesMinor,boolean sacredCeremony,boolean personalData,boolean hateSpeechSuspected){}public record SubmissionResponse(UUID id,String userId,UUID challengeId,UUID postId,UUID cultureContributionId,List<UUID>mediaIds,String languageCode,String translation,CultureChallengeSubmission.Status status,String moderationReason,Instant createdAt,Instant withdrawnAt){public static SubmissionResponse from(CultureChallengeSubmission s){return new SubmissionResponse(s.getId(),s.getUserId(),s.getChallengeId(),s.getPostId(),s.getCultureContributionId(),s.getMediaIds(),s.getLanguageCode(),s.getTranslation(),s.getStatus(),s.getModerationReason(),s.getCreatedAt(),s.getWithdrawnAt());}}public record ParticipationResponse(UUID challengeId,Instant joinedAt,Instant completedAt){} }
